def solve(a, b, x, y, n):
    if a <= x and b <= y:
        return a * b

    diff_a = max(0, a - x)
    diff_b = max(0, b - y)

    if diff_a + diff_b <= n:
        return max(x, a - diff_a) * max(y, b - diff_b)

    operations = min(diff_a, n)
    a -= operations
    n -= operations

    operations = min(diff_b, n)
    b -= operations

    return a * b

def main():
    t = int(input())
    for _ in range(t):
        a, b, x, y, n = map(int, input().split())
        print(solve(a, b, x, y, n))

if __name__ == "__main__":
    main()

def min_product_after_operations(t, test_cases):
    results = []
    for case in test_cases:
        a, b, x, y, n = case
        while n > 0:
            if a - 1 >= x and b - 1 >= y:
                if (a - 1 - x) * (b - 1) > (a - 1) * (b - 1 - y):
                    a -= 1
                else:
                    b -= 1
            elif a - 1 >= x:
                a -= 1
            elif b - 1 >= y:
                b -= 1
            else:
                break
            n -= 1
        results.append(a * b)
    return results

import sys

def main():
    input = sys.stdin.read
    data = input().split()
